SELECT t.PROC_INST_ID_ AS procInstId, t.TASK_DEF_KEY_ AS elementId, t.NAME_ AS elementName, t.ASSIGNEE_ AS assignee, t.ASSIGNEE_NAME AS assigneeName FROM AF_RU_TASK t WHERE t.PROC_INST_ID_ IN
#{pid}
AND t.ASSIGNEE_ IN
#{uid}

SELECT bv.process_num AS processNumber, bvm.element_id AS elementId, bvm.element_name AS elementName, bvmp.assignee AS assignee, bvmp.assignee_name AS assigneeName FROM t_bpm_variable bv INNER JOIN t_bpm_variable_multiplayer bvm ON bvm.variable_id = bv.id AND bvm.is_del = 0 INNER JOIN t_bpm_variable_multiplayer_personnel bvmp ON bvmp.variable_multiplayer_id = bvm.id AND bvmp.is_del = 0 WHERE bv.process_num IN
#{pn}
AND bvmp.assignee IN
#{uid}
AND CAST(REPLACE(bvm.element_id, 'task', '') AS UNSIGNED) >= ( SELECT MIN(CAST(REPLACE(t.TASK_DEF_KEY_, 'task', '') AS UNSIGNED)) FROM AF_RU_TASK t INNER JOIN bpm_business_process bbp2 ON bbp2.PROC_INST_ID_ = t.PROC_INST_ID_ WHERE bbp2.BUSINESS_NUMBER = bv.process_num AND bbp2.process_state = 1 )
AND CAST(REPLACE(bvm.element_id, 'task', '') AS UNSIGNED) > ( SELECT MIN(CAST(REPLACE(t.TASK_DEF_KEY_, 'task', '') AS UNSIGNED)) FROM AF_RU_TASK t INNER JOIN bpm_business_process bbp2 ON bbp2.PROC_INST_ID_ = t.PROC_INST_ID_ WHERE bbp2.BUSINESS_NUMBER = bv.process_num AND bbp2.process_state = 1 )
